    /// <summary> 
    /// Write a java function to set all odd bits of a given number.
    /// 
    /// Note: You can write Java code in Python.
    /// 
    /// Example:
    /// >>> OddBitSetNumber(10)
    /// >>> 15
    /// >>> OddBitSetNumber(20)
    /// >>> 21
    /// >>> OddBitSetNumber(30)
    /// >>> 31
    /// </summary>
    int count = 0;
    int temp = n;
    while (temp > 0)
    {
        if ((count & 1) == 0)
            n |= (1 << count);
        count += 1;
        temp >>= 1;
    }
    return n;
}

