    // Calculate the Geometric Progression Series
    // Formula: (a * (1 - 1 / (1 + n)) ** r) / (1 - 1 / (1 + n))

    var m = (n - 1) / n;
    var temp = 1;
    var sum = 0;

    for (int i = 1; i <= n; i++) {
        sum += temp;
        temp = (temp - m) * r;
    }

    return a * sum;
}

