using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using KellermanSoftware.CompareNetObjects;

namespace Solution
{
    public class Program
    {
        public static int MinCoins (List<int> coins, int m, int V) 
        {

            if (V == 0) 
                return 0;
            var res = Int32.MaxValue;
            for (int i = 0; i < m; i++) 
            {
                if (coins[i] <= V) 
                {
                    var subRes = MinCoins(coins, m, V - coins[i]);
                    if (subRes != Int32.MaxValue && subRes + 1 < res) 
                        res = subRes + 1;
                }
            }
            return res;
        }

