using System.Linq;
using System.Text.RegularExpressions;
using KellermanSoftware.CompareNetObjects;

namespace Solution
{
    public class Program
    {
        public static List<int> GetLudic (int n) 
        {

            List<int> ludics = new List<int>();
            for (int i = 1; i <= n; i++)
                ludics.Add(i);
            int index = 1;
            while (index != ludics.Count) {
                int first_ludic = ludics[index];
                int remove_index = index + first_ludic;
                while (remove_index < ludics.Count) {
                    ludics.RemoveAt(remove_index);
                    remove_index = remove_index + first_ludic - 1;
                }
                index += 1;
            }
            return ludics;
        }

