    // Declare an array of prime numbers
    int[] prime = new int[n + 1];
    // Set all numbers to be prime
    for (int i = 0; i < prime.Length; i++)
        prime[i] = 1;
    // Initialize sum to zero
    int sum = 0;
    // Loop from 2 to n
    for (int i = 2; i <= n; i++)
    {
        // If i is prime, then update sum
        if (prime[i] == 1)
            sum += i;
        // Find all prime numbers less than i
        for (int j = i * i; j <= n; j += i)
            prime[j] = 0;
    }
    return sum;
}

