    /// <summary>
    /// 
    /// Counts the total unset bits from 1 to n.
    /// 
    /// </summary>
    int cnt = 0;

    int temp = 1;

    for (int i = 1; i <= n; i++) 
    {
        temp = i;
        while (temp > 0) 
        {
            if ((temp & 1) == 0) 
            {
                cnt += 1;
            }
            temp = temp >> 1;
        }
    }
    return cnt;
}

